p = Path("index.html")
t = p.read_text(encoding="utf-8", errors="replace")

for key, block in [("W7", W7_BLOCK), ("W8", W8_BLOCK), ("W10", W10_BLOCK)]:
    pattern = rf"{key}:\(\)=>[\s\S]*?(?=(?:W\d+:\(\)=>)|(?:const pcvViews=\{{)|(?:F08:))"
    # also allow end before F08 or closing
    t2, n = re.subn(pattern, block, t, count=1)
    if n != 1:
        # try alternate end
        pattern2 = rf"{key}:\(\)=>[\s\S]*?(?=(?:W\d+:\(\)=>)|(?:F08:)|(?:const pcvViews=\{{)|(?:\}};\s*\n))"
        t2, n = re.subn(pattern2, block, t, count=1)
    if n != 1:
        raise SystemExit(f"{key} replace failed matches={n}")
    t = t2
    print(f"{key} installed")

if "function l3View" not in t:
    raise SystemExit("Safety: l3View missing")
if "RECOVERY GAP SUMMARY" not in t and "PERFORMANCE GAP OVERVIEW" not in t:
    raise SystemExit("Safety: W7 content missing")
if "INTERVENTION OPTIONS" not in t:
    raise SystemExit("Safety: W8 content missing")
if "KEY LESSONS LEARNT" not in t:
    raise SystemExit("Safety: W10 content missing")

p.write_text(t, encoding="utf-8")
print("W7 (2 views) + W8 (2 views) + W10 installed successfully")
